import {readFile,readdir} from 'node:fs/promises';import {createHash} from 'node:crypto';import path from 'node:path';
export const CLIENT_FILES=['game-feel.mjs','feel.css','supports.css','bonus-rules.mjs','experiment.css','index.html','app.mjs','alerts.mjs','engine.mjs','board.mjs','bot-worker.mjs','ui.mjs','session.mjs','style.css','refine.css','game-v2.css','tile-motion.mjs','tile-inventory.mjs','match-snapshot.mjs','room-cache.mjs','profile-art.mjs','match-records.mjs','privacy.html','favicon.svg','account.mjs','firebase-config.mjs','firebase.mjs','login.html','login.mjs','delete-account.html'];
export async function clientBundle(root){const publicRoot=path.join(root,'public'),assets=(await readdir(path.join(publicRoot,'assets'))).filter(n=>/^[A-Za-z0-9_-]+\.(png|webp|woff2|txt)$/.test(n)&&n!=='renkio-hero.webp').map(n=>'assets/'+n);const files=await Promise.all([...CLIENT_FILES,...assets].sort().map(async name=>{const data=await readFile(path.join(publicRoot,name));return {path:name,sha256:createHash('sha256').update(data).digest('hex'),data:data.toString('base64')}}));const revision=createHash('sha256').update(files.map(f=>f.path+':'+f.sha256).join('\n')).digest('hex');return {format:1,revision,files}}
